            documentId: id,
            market: String(old.rows[0].market),
            locale: String(old.rows[0].locale),
            revisionId: String(revision.rows[0].id),
            snapshot: old.rows[0].payload,
            kind: old.rows[0].kind,
            userId: auth.user.id,
            sourceRevisionId: parsed.data.revisionId
